const {THREE,RAPIER,sim,world,root}=game;
const near=game.entities.find(e=>e.id==='near-bank'&&!e.removed);
const far=game.entities.find(e=>e.id==='far-bank'&&!e.removed);
const garden=new THREE.Group();garden.name='Living vine bridge';root.add(garden);
const geometries=[new THREE.CylinderGeometry(1,1,1,8),new THREE.SphereGeometry(1,10,6)];
const bark=new THREE.MeshStandardMaterial({color:0x426329,roughness:.95});
const young=new THREE.MeshStandardMaterial({color:0x78a83d,roughness:.85});
const foliage=new THREE.MeshStandardMaterial({color:0x4caa48,roughness:.8});
const materials=[bark,young,foliage];
let target=false,extent=0,time=0,disposed=false;
const segments=[];
let start=0,end=0,y=0,z=0,length=0,unit=0;
function mesh(geometry,material,parent){const m=new THREE.Mesh(geometry,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
if(near&&far){
 start=near.position.x+near.half.x-.5;
 end=far.position.x-far.half.x+.5;
 y=Math.max(near.position.y+near.half.y,far.position.y+far.half.y);
 const lo=Math.max(near.position.z-near.half.z,far.position.z-far.half.z)+1.2;
 const hi=Math.min(near.position.z+near.half.z,far.position.z+far.half.z)-1.2;
 z=THREE.MathUtils.clamp(0,lo,hi);
 length=end-start;
 const count=Math.min(64,Math.max(1,Math.ceil(length/.25)));unit=length/count;
 for(let i=0;i<count;i++){
  const group=new THREE.Group();group.position.set(start+i*unit,y,z);group.visible=false;garden.add(group);
  for(let j=0;j<10;j++){
   const vine=mesh(geometries[0],j%3===0?young:bark,group);
   vine.position.set(unit/2,-.10,-.99+j*.22);vine.rotation.z=Math.PI/2;vine.scale.set(.115,unit+.006,.115);
  }
  const rib=mesh(geometries[0],young,group);rib.rotation.x=Math.PI/2;rib.position.set(unit*.6,-.035,0);rib.scale.set(.04,2.18,.04);
  const leaves=[];
  for(const side of [-1,1]){
   const stem=mesh(geometries[0],young,group);stem.position.set(unit*.65,.06,side*1.10);stem.rotation.x=side*.7;stem.scale.set(.023,.28,.023);
   const leaf=mesh(geometries[1],foliage,group);leaf.name='Sprouting leaf';leaf.position.set(unit*.65,.17,side*1.27);leaf.rotation.set(side*.3,side*.5,side*.2);leaves.push(leaf);
  }
  segments.push({group,leaves,collider:null,f:0,index:i});
 }
 const bulb=mesh(geometries[1],young,garden);bulb.position.set(start-.12,y+.08,z-1.15);bulb.scale.set(.24,.17,.22);
}
function update(){
 for(const s of segments){
  const f=THREE.MathUtils.clamp((extent-s.index*unit)/unit,0,1);
  s.group.visible=f>.001;s.group.scale.x=Math.max(.001,f);
  if(Math.abs(f-s.f)>.000001){
   if(f>.001){
    const center={x:start+s.index*unit+unit*f/2,y:y-.10,z};
    if(!s.collider){s.collider=world.createCollider(RAPIER.ColliderDesc.cuboid(unit*f/2,.11,1.1).setTranslation(center.x,center.y,center.z).setFriction(.9));}
    else {s.collider.setShape(new RAPIER.Cuboid(unit*f/2,.11,1.1));s.collider.setTranslation(center);}
   }else if(s.collider){if(s.collider.isValid())world.removeCollider(s.collider,true);s.collider=null;}
   s.f=f;
  }
  const bloom=THREE.MathUtils.clamp((f-.35)/.65,0,1);
  for(let k=0;k<s.leaves.length;k++){
   const leaf=s.leaves[k];leaf.visible=bloom>0;leaf.scale.set(.19*bloom,.045*bloom,.34*bloom);
   leaf.rotation.x=(k===0?-.3:.3)+Math.sin(time*2+s.index*.6+k)*.09*bloom;
  }
 }
}
return {
 use(){
  if(disposed)return;
  if(!near||!far||length<=0){game.say('This vine needs the two banks of the broken bridge.');return;}
  target=!target;
  game.say(target?'The vines are growing along the marked crossing. Let the green path reach the far bank.':'The vines are curling back! Stay on a bank.');
  game.sound(target?240:390,.22,.07,target?520:150);
 },
 step(dt){
  if(disposed)return;time+=dt;
  const before=extent;extent=THREE.MathUtils.clamp(extent+(target?1:-1)*1.8*dt,0,length);update();
  if(target&&before<length&&extent===length)game.say('The living bridge is rooted. Walk across; F retracts it.');
  if(!target&&before>0&&extent===0)game.say('The bridge is curled away. F grows it again.');
 },
 dispose(){
  if(disposed)return;disposed=true;
  for(const s of segments)if(s.collider&&s.collider.isValid())world.removeCollider(s.collider,true);
  garden.removeFromParent();for(const g of geometries)g.dispose();for(const m of materials)m.dispose();
 }
};

