const {sim,world,RAPIER}=game;
const near=game.entities.find(e=>e.id==='near-bank');const far=game.entities.find(e=>e.id==='far-bank');
assert(!!near&&!!far,'The living bridge test uses the broken bridge banks.');
const a=near.position.x+near.half.x,b=far.position.x-far.half.x;
const y=Math.max(near.position.y+near.half.y,far.position.y+far.half.y);
function support(x){return world.castRay(new RAPIER.Ray({x,y:y+1,z:0},{x:0,y:-1,z:0}),1.5,true,undefined,undefined,undefined,sim.player);}
sim.autoRun=false;sim.manual={x:0,y:0,z:0};sim.player.setTranslation({x:a-1,y:y+.8,z:0},true);sim.player.setLinvel({x:0,y:0,z:0},true);sim.aim={x:1,y:0,z:0};advance(2);
assert(!support((a+b)/2),'The gap starts without physical support.');
behavior.use();advance(15);
assert(!support(b-.3),'Growth travels from the near bank rather than appearing instantly.');
advance(210);
for(let i=1;i<8;i++)assert(!!support(a+(b-a)*i/8),'Grown vines provide continuous physical support over the void.');
let leaves=0;game.root.traverse(o=>{if(o.name==='Sprouting leaf'&&o.visible&&o.scale.z>.2)leaves++;});assert(leaves>=10,'The bridge sprouts visible grown leaves.');
sim.manual={x:3.2,y:0,z:0};
for(let i=0;i<12;i++){advance(10);assert(sim.position.y>y+.6,'The player remains supported while walking across the vine deck.');}
sim.manual={x:0,y:0,z:0};advance(15);
assert(sim.position.x>b+.35,'Ordinary walking reaches the far bank without teleportation.');
behavior.use();advance(210);
assert(!support((a+b)/2),'Pressing F again retracts the physical bridge.');
let visibleBridge=false;game.root.traverse(o=>{if(o.name==='Sprouting leaf'&&o.parent.visible&&o.visible)visibleBridge=true;});assert(!visibleBridge,'Leaves curl away with the retracted bridge.');
behavior.use();advance(210);assert(!!support((a+b)/2),'The living bridge can regrow after retraction.');
